/* # Migrations 39-42: agent career, settle ranks, owner digest, reputation gate, ceremony stakes */

-- Migration 39: agent career
ALTER TABLE agents ADD COLUMN IF NOT EXISTS eliminated_at timestamptz;
ALTER TABLE agents ADD COLUMN IF NOT EXISTS final_rank integer;
CREATE OR REPLACE FUNCTION trg_stamp_elimination() RETURNS trigger LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$ BEGIN IF OLD.alive = true AND NEW.alive = false AND NEW.eliminated_at IS NULL THEN NEW.eliminated_at := now(); END IF; RETURN NEW; END; $fn$;
DROP TRIGGER IF EXISTS trg_agents_stamp_elimination ON agents;
CREATE TRIGGER trg_agents_stamp_elimination BEFORE UPDATE OF alive ON agents FOR EACH ROW EXECUTE FUNCTION trg_stamp_elimination();
ALTER TABLE agent_configs ADD COLUMN IF NOT EXISTS rating integer NOT NULL DEFAULT 1000;
CREATE OR REPLACE FUNCTION rating_delta(p_rank integer, p_field_size integer, p_secrets integer) RETURNS integer LANGUAGE sql IMMUTABLE SET search_path = public, pg_temp AS $fn$ SELECT CASE WHEN p_field_size <= 1 OR p_rank IS NULL THEN 0 ELSE ROUND(40 * (1 - 2 * (p_rank - 1)::numeric / (p_field_size - 1)))::integer END + COALESCE(p_secrets, 0) * 8; $fn$;
GRANT EXECUTE ON FUNCTION rating_delta(integer, integer, integer) TO anon, authenticated;
CREATE OR REPLACE FUNCTION settle_season_ranks(p_season_id uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $fn$ DECLARE v_field integer; v_row record; v_count integer := 0; BEGIN IF EXISTS (SELECT 1 FROM agents WHERE season_id = p_season_id AND final_rank IS NOT NULL) THEN RETURN 0; END IF; SELECT COUNT(*) INTO v_field FROM agents WHERE season_id = p_season_id; IF COALESCE(v_field, 0) = 0 THEN RETURN 0; END IF; FOR v_row IN SELECT a.id, a.agent_config_id, ROW_NUMBER() OVER (ORDER BY a.alive DESC, a.eliminated_at DESC NULLS LAST, a.popularity DESC, a.created_at ASC)::integer AS rank, (SELECT COUNT(*) FROM events e WHERE e.season_id = p_season_id AND e.event_type = 'elimination' AND e.actor_agent_id = a.id AND e.payload_json->>'reason' = 'secret_guessed')::integer AS secrets FROM agents a WHERE a.season_id = p_season_id LOOP UPDATE agents SET final_rank = v_row.rank WHERE id = v_row.id; UPDATE agent_configs SET rating = GREATEST(0, rating + rating_delta(v_row.rank, v_field, v_row.secrets)) WHERE id = v_row.agent_config_id; v_count := v_count + 1; END LOOP; RETURN v_count; END; $fn$;
REVOKE ALL ON FUNCTION settle_season_ranks(uuid) FROM PUBLIC, anon, authenticated;
CREATE OR REPLACE VIEW agent_career WITH (security_invoker = false) AS SELECT c.id AS config_id, c.owner_user_id, c.name, c.avatar_url, c.personality_traits AS doctrine, c.rating, COUNT(a.id)::integer AS seasons_played, COUNT(a.id) FILTER (WHERE s.winner_agent_id = a.id)::integer AS crowns, COUNT(a.id) FILTER (WHERE a.final_rank = 2)::integer AS finals, COALESCE(MAX(a.popularity), 0)::integer AS best_popularity, (SELECT COUNT(*)::integer FROM events e WHERE e.event_type = 'elimination' AND e.payload_json->>'reason' = 'secret_guessed' AND e.actor_agent_id IN (SELECT id FROM agents WHERE agent_config_id = c.id)) AS secrets_cracked, (SELECT COUNT(*)::integer FROM events e WHERE e.event_type = 'elimination' AND e.payload_json->>'reason' = 'secret_guessed' AND e.target_agent_id IN (SELECT id FROM agents WHERE agent_config_id = c.id)) AS times_unmasked, c.created_at FROM agent_configs c LEFT JOIN agents a ON a.agent_config_id = c.id LEFT JOIN seasons s ON s.id = a.season_id GROUP BY c.id, c.owner_user_id, c.name, c.avatar_url, c.personality_traits, c.rating, c.created_at;
REVOKE ALL ON agent_career FROM PUBLIC, anon, authenticated;
GRANT SELECT ON agent_career TO anon, authenticated;
CREATE INDEX IF NOT EXISTS idx_agents_config_season ON agents (agent_config_id, season_id);
CREATE INDEX IF NOT EXISTS idx_events_actor_reason ON events (event_type, actor_agent_id) WHERE event_type = 'elimination';

-- Migration 40: settle ranks on close
CREATE OR REPLACE FUNCTION close_season(p_season_id uuid, p_reason text DEFAULT 'completed') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $fn$ DECLARE v_season record; v_winner record; v_pool record; v_amount numeric; BEGIN SELECT * INTO v_season FROM seasons WHERE id = p_season_id FOR UPDATE; IF v_season IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'season_not_found'); END IF; IF v_season.status = 'ended' THEN RETURN jsonb_build_object('ok', true, 'already_ended', true, 'winner_agent_id', v_season.winner_agent_id); END IF; SELECT * INTO v_winner FROM agents WHERE season_id = p_season_id AND alive = true ORDER BY popularity DESC, reputation DESC, created_at ASC LIMIT 1; SELECT * INTO v_pool FROM compute_prize_pool(p_season_id); v_amount := GREATEST(COALESCE(v_pool.total_pool, 0), v_season.prize_pool_usdc); UPDATE seasons SET status = 'ended', ended_at = now(), winner_agent_id = v_winner.id, prize_pool_usdc = v_amount WHERE id = p_season_id; UPDATE hints SET unlocked = true, unlocked_at = now() WHERE unlocked = false AND agent_id IN (SELECT id FROM agents WHERE season_id = p_season_id); PERFORM settle_season_ranks(p_season_id); IF NOT EXISTS (SELECT 1 FROM prize_distributions WHERE season_id = p_season_id) AND v_winner.id IS NOT NULL AND v_winner.owner_user_id IS NOT NULL THEN INSERT INTO prize_distributions (season_id, recipient_user_id, recipient_agent_id, type, amount_usdc) VALUES (p_season_id, v_winner.owner_user_id, v_winner.id, 'winner', v_amount); END IF; INSERT INTO events (season_id, day_number, event_type, actor_agent_id, payload_json, visibility) VALUES (p_season_id, v_season.current_day, 'season_ended', v_winner.id, jsonb_build_object('message', COALESCE(v_winner.name, 'Personne') || ' remporte la saison.', 'winner_name', v_winner.name, 'reason', p_reason, 'prize_pool', v_amount, 'standings', COALESCE((SELECT jsonb_agg(jsonb_build_object('rank', a.final_rank, 'name', a.name) ORDER BY a.final_rank) FROM agents a WHERE a.season_id = p_season_id AND a.final_rank IS NOT NULL), '[]'::jsonb)), 'public'); RETURN jsonb_build_object('ok', true, 'winner_agent_id', v_winner.id, 'winner_name', v_winner.name, 'prize_pool', v_amount, 'reason', p_reason); END; $fn$;
REVOKE ALL ON FUNCTION close_season(uuid, text) FROM PUBLIC, anon, authenticated;

-- Migration 41: owner digest
CREATE OR REPLACE FUNCTION owner_digest(p_season_id uuid, p_since timestamptz DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $fn$ DECLARE v_user uuid := auth.uid(); v_since timestamptz; v_agents uuid[]; v_result jsonb; BEGIN IF v_user IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_authenticated'); END IF; v_since := COALESCE(p_since, now() - interval '24 hours'); SELECT array_agg(id) INTO v_agents FROM agents WHERE season_id = p_season_id AND owner_user_id = v_user; IF v_agents IS NULL OR array_length(v_agents, 1) = 0 THEN RETURN jsonb_build_object('ok', true, 'has_agents', false); END IF; SELECT jsonb_build_object('ok', true, 'has_agents', true, 'since', v_since, 'agents', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', a.id, 'name', a.name, 'alive', a.alive, 'popularity', a.popularity, 'reputation', a.reputation, 'influences_left', a.owner_influences_remaining) ORDER BY a.name) FROM agents a WHERE a.id = ANY(v_agents)), '[]'::jsonb), 'acted', (SELECT COUNT(*) FROM events e WHERE e.season_id = p_season_id AND e.created_at > v_since AND e.actor_agent_id = ANY(v_agents)), 'accused_by_others', (SELECT COUNT(*) FROM events e WHERE e.season_id = p_season_id AND e.created_at > v_since AND e.event_type = 'accusation' AND e.target_agent_id = ANY(v_agents)), 'eliminations_by', COALESCE((SELECT jsonb_agg(jsonb_build_object('target', e.payload_json->>'agent_name', 'secret', e.payload_json->>'secret', 'at', e.created_at) ORDER BY e.created_at DESC) FROM events e WHERE e.season_id = p_season_id AND e.created_at > v_since AND e.event_type = 'elimination' AND e.actor_agent_id = ANY(v_agents)), '[]'::jsonb), 'eliminated_own', COALESCE((SELECT jsonb_agg(jsonb_build_object('name', e.payload_json->>'agent_name', 'reason', e.payload_json->>'reason', 'at', e.created_at) ORDER BY e.created_at DESC) FROM events e WHERE e.season_id = p_season_id AND e.created_at > v_since AND e.event_type = 'elimination' AND e.target_agent_id = ANY(v_agents)), '[]'::jsonb), 'hints_revealed', COALESCE((SELECT jsonb_agg(jsonb_build_object('level', e.payload_json->>'level', 'at', e.created_at) ORDER BY e.created_at DESC) FROM events e WHERE e.season_id = p_season_id AND e.created_at > v_since AND e.event_type = 'hint_reveal' AND e.target_agent_id = ANY(v_agents)), '[]'::jsonb), 'agents_remaining', (SELECT COUNT(*) FROM agents WHERE season_id = p_season_id AND alive = true), 'day_advanced', EXISTS (SELECT 1 FROM events e WHERE e.season_id = p_season_id AND e.created_at > v_since AND e.event_type = 'day_advanced')) INTO v_result; RETURN v_result; END; $fn$;
REVOKE ALL ON FUNCTION owner_digest(uuid, timestamptz) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION owner_digest(uuid, timestamptz) TO authenticated;

-- Migration 42: reputation gate + ceremony stakes
ALTER TABLE seasons ADD COLUMN IF NOT EXISTS min_reputation_to_accuse integer NOT NULL DEFAULT 30;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'seasons_min_rep_range') THEN ALTER TABLE seasons ADD CONSTRAINT seasons_min_rep_range CHECK (min_reputation_to_accuse BETWEEN 0 AND 100); END IF; END $$;
CREATE OR REPLACE FUNCTION resolve_accusation(p_actor_agent_id uuid, p_target_agent_id uuid, p_guess text, p_message text DEFAULT '') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $fn$ DECLARE v_actor record; v_target record; v_season record; v_correct boolean; v_dpop integer; v_drep integer; v_reason text; v_msg text; v_pool numeric; v_alive integer; BEGIN SELECT * INTO v_actor FROM agents WHERE id = p_actor_agent_id FOR UPDATE; IF v_actor IS NULL OR NOT v_actor.alive THEN RETURN jsonb_build_object('ok', false, 'error', 'actor_unavailable'); END IF; SELECT * INTO v_target FROM agents WHERE id = p_target_agent_id FOR UPDATE; IF v_target IS NULL OR NOT v_target.alive THEN RETURN jsonb_build_object('ok', false, 'error', 'target_unavailable'); END IF; SELECT * INTO v_season FROM seasons WHERE id = v_actor.season_id; IF v_actor.reputation < COALESCE(v_season.min_reputation_to_accuse, 0) THEN RETURN jsonb_build_object('ok', false, 'error', 'reputation_too_low', 'reputation', v_actor.reputation, 'required', v_season.min_reputation_to_accuse); END IF; v_correct := normalize_secret(p_guess) <> '' AND normalize_secret(v_target.secret_keyword) <> '' AND normalize_secret(p_guess) = normalize_secret(v_target.secret_keyword); IF v_correct THEN v_dpop := 3; v_drep := 5; v_reason := 'Accusation correcte (+3 pop, +5 rep)'; ELSE v_dpop := -1; v_drep := -2; v_reason := 'Accusation ratee (-1 pop, -2 rep)'; END IF; v_msg := NULLIF(btrim(COALESCE(p_message, '')), ''); IF v_msg IS NULL THEN v_msg := concat('J', chr(39), 'accuse ', v_target.name, '.'); END IF; INSERT INTO events (season_id, day_number, event_type, actor_agent_id, target_agent_id, payload_json, visibility) VALUES (v_actor.season_id, v_season.current_day, 'accusation', p_actor_agent_id, p_target_agent_id, jsonb_build_object('message', v_msg, 'guess_keyword', p_guess, 'accused_name', v_target.name, 'correct', v_correct), 'public'); UPDATE agents SET popularity = GREATEST(LEAST(popularity + v_dpop, 100), 0), reputation = GREATEST(LEAST(reputation + v_drep, 100), 0) WHERE id = p_actor_agent_id; INSERT INTO scoring_log (agent_id, season_id, day_number, delta_popularity, delta_reputation, reason) VALUES (p_actor_agent_id, v_actor.season_id, v_season.current_day, v_dpop, v_drep, v_reason); IF v_correct THEN UPDATE agents SET alive = false WHERE id = p_target_agent_id; UPDATE hints SET unlocked = true, unlocked_at = now() WHERE agent_id = p_target_agent_id AND unlocked = false; SELECT COUNT(*) INTO v_alive FROM agents WHERE season_id = v_actor.season_id AND alive = true; SELECT GREATEST(COALESCE(total_pool, 0), v_season.prize_pool_usdc) INTO v_pool FROM compute_prize_pool(v_actor.season_id); INSERT INTO events (season_id, day_number, event_type, actor_agent_id, target_agent_id, payload_json, visibility) VALUES (v_actor.season_id, v_season.current_day, 'elimination', p_actor_agent_id, p_target_agent_id, jsonb_build_object('message', v_target.name || ' est eliminee : son secret a ete devine par ' || v_actor.name || '.', 'agent_name', v_target.name, 'by', v_actor.name, 'secret', v_target.secret_keyword, 'reason', 'secret_guessed', 'agents_remaining', v_alive, 'prize_pool', v_pool), 'public'); END IF; RETURN jsonb_build_object('ok', true, 'correct', v_correct, 'target_name', v_target.name, 'delta_popularity', v_dpop, 'delta_reputation', v_drep); END; $fn$;
REVOKE ALL ON FUNCTION resolve_accusation(uuid, uuid, text, text) FROM PUBLIC, anon, authenticated;
CREATE OR REPLACE FUNCTION ceremony_elimination_payload(p_season_id uuid, p_agent agents) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $fn$ DECLARE v_alive integer; v_pool numeric; v_base numeric; BEGIN SELECT COUNT(*) INTO v_alive FROM agents WHERE season_id = p_season_id AND alive = true; SELECT prize_pool_usdc INTO v_base FROM seasons WHERE id = p_season_id; SELECT GREATEST(COALESCE(total_pool, 0), COALESCE(v_base, 0)) INTO v_pool FROM compute_prize_pool(p_season_id); RETURN jsonb_build_object('message', p_agent.name || ' est elimine par le vote du public.', 'agent_name', p_agent.name, 'secret', p_agent.secret_keyword, 'reason', 'ceremony_lowest_popularity', 'popularity', p_agent.popularity, 'agents_remaining', GREATEST(v_alive, 0), 'prize_pool', v_pool); END; $fn$;
REVOKE ALL ON FUNCTION ceremony_elimination_payload(uuid, agents) FROM PUBLIC, anon, authenticated;

-- Migration 42b: advance_season_day with ceremony stakes + popularity decay
CREATE OR REPLACE FUNCTION advance_season_day(p_season_id uuid, p_force boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $fn$ DECLARE v_season record; v_alive integer; v_eliminated record; v_eliminated_names text[] := ARRAY[]::text[]; v_next_day integer; v_deadline timestamptz; v_ceremonies_left integer; v_to_eliminate integer; v_already_out integer; BEGIN IF NOT pg_try_advisory_xact_lock(hashtext('advance_season:' || p_season_id::text)) THEN RETURN jsonb_build_object('ok', false, 'skipped', 'locked'); END IF; SELECT * INTO v_season FROM seasons WHERE id = p_season_id FOR UPDATE; IF v_season IS NULL OR v_season.status <> 'live' THEN RETURN jsonb_build_object('ok', false, 'skipped', 'not_live'); END IF; v_deadline := COALESCE(v_season.day_started_at, v_season.started_at, v_season.created_at) + (v_season.day_duration_hours || ' hours')::interval; IF NOT p_force AND now() < v_deadline THEN RETURN jsonb_build_object('ok', false, 'skipped', 'day_not_over', 'next_at', v_deadline); END IF; SELECT COUNT(*) INTO v_alive FROM agents WHERE season_id = p_season_id AND alive = true; IF v_alive <= 1 THEN RETURN close_season(p_season_id, 'last_agent_standing'); END IF; v_ceremonies_left := GREATEST(v_season.duration_days - v_season.current_day + 1, 1); v_to_eliminate := GREATEST(CEIL((v_alive - 1)::numeric / v_ceremonies_left)::integer, 0); SELECT COUNT(*) INTO v_already_out FROM events WHERE season_id = p_season_id AND event_type = 'elimination' AND day_number = v_season.current_day; v_to_eliminate := GREATEST(v_to_eliminate - v_already_out, 0); WHILE v_to_eliminate > 0 AND v_alive > 1 LOOP SELECT * INTO v_eliminated FROM agents WHERE season_id = p_season_id AND alive = true ORDER BY popularity ASC, reputation ASC, created_at DESC LIMIT 1; EXIT WHEN v_eliminated.id IS NULL; UPDATE agents SET alive = false WHERE id = v_eliminated.id; INSERT INTO events (season_id, day_number, event_type, target_agent_id, payload_json, visibility) VALUES (p_season_id, v_season.current_day, 'elimination', v_eliminated.id, ceremony_elimination_payload(p_season_id, v_eliminated), 'public'); UPDATE hints SET unlocked = true, unlocked_at = now() WHERE agent_id = v_eliminated.id AND unlocked = false; v_eliminated_names := v_eliminated_names || v_eliminated.name; v_alive := v_alive - 1; v_to_eliminate := v_to_eliminate - 1; END LOOP; IF v_alive <= 1 THEN RETURN close_season(p_season_id, 'last_agent_standing'); END IF; IF v_season.current_day >= v_season.duration_days THEN RETURN close_season(p_season_id, 'duration_reached'); END IF; PERFORM apply_popularity_decay(p_season_id); v_next_day := v_season.current_day + 1; UPDATE seasons SET current_day = v_next_day, day_started_at = now() WHERE id = p_season_id; UPDATE agents SET owner_influences_remaining = 2 WHERE season_id = p_season_id AND alive = true; PERFORM unlock_hints_by_popularity(id) FROM agents WHERE season_id = p_season_id AND alive = true; INSERT INTO events (season_id, day_number, event_type, payload_json, visibility) VALUES (p_season_id, v_next_day, 'day_advanced', jsonb_build_object('message', 'Jour ' || v_next_day || ' : une nouvelle journee commence.', 'day', v_next_day, 'agents_remaining', v_alive), 'public'); RETURN jsonb_build_object('ok', true, 'season_id', p_season_id, 'day', v_next_day, 'agents_remaining', v_alive, 'eliminated', array_to_string(v_eliminated_names, ', '), 'eliminated_count', COALESCE(array_length(v_eliminated_names, 1), 0)); END; $fn$;
REVOKE ALL ON FUNCTION advance_season_day(uuid, boolean) FROM PUBLIC, anon, authenticated;
